<template>
  <div class="admin-shell">
    <el-container class="admin-layout">
      <el-aside class="admin-aside" width="270px">
        <div class="brand-block"><div class="brand-mark">FF</div><div><div class="brand-name">Football Admin</div><div class="brand-sub">赛事数据运营控制台</div></div></div>
        <nav class="side-section" aria-label="管理后台导航"><div class="side-label">工作台</div><el-menu :default-active="activeMenu" class="admin-menu" aria-label="后台功能菜单" @select="activeMenu = $event"><el-menu-item index="dashboard">总览</el-menu-item><el-menu-item index="matches">比赛工作台</el-menu-item><el-menu-item index="sources">数据源控制台</el-menu-item><el-menu-item index="models">模型实验室</el-menu-item><el-menu-item index="analytics">行为分析</el-menu-item><el-menu-item index="users">用户运营</el-menu-item><el-menu-item index="config">系统配置</el-menu-item><el-menu-item index="logs">审计日志</el-menu-item></el-menu></nav>
        <div class="side-section side-meta"><div class="side-label">当前概览</div><div class="meta-item"><span>比赛维护</span><strong>{{ crawlerMatchTotal }}</strong></div><div class="meta-item"><span>用户</span><strong>{{ users.length }}</strong></div><div class="meta-item"><span>Agent 完成</span><strong>{{ agentMetrics?.completed ?? '—' }}</strong></div><div class="meta-item"><span>日志</span><strong>{{ logs.length }}</strong></div></div>
      </el-aside>
      <el-container>
        <el-header class="admin-header"><div class="header-left"><span v-if="lastReloadAt" class="last-reload">最近刷新 {{ lastReloadAt }}</span></div><div class="header-actions"><el-input v-if="activeMenu === 'users'" v-model="userKeyword" class="head-search" placeholder="搜索用户名" clearable @change="loadUsers" /><el-button @click="reloadAll">刷新</el-button><el-button v-if="activeMenu === 'matches'" type="success" plain @click="syncMatchesNow">更新主爬虫数据</el-button><el-button type="primary" plain @click="goFront">返回前台</el-button></div></el-header>
        <el-main id="app-main" class="admin-main" tabindex="-1">
          <el-alert v-if="activeMenu === 'dashboard' && sectionErrors.summary" class="summary-alert reveal" :title="sectionErrors.summary" type="warning" show-icon :closable="false" />
          <section v-if="activeMenu === 'dashboard'" class="dashboard-top reveal"><el-card v-for="item in metrics" :key="item.label" class="metric-card" shadow="never"><div class="metric-label">{{ item.label }}</div><div class="metric-value">{{ item.value }}</div><div class="metric-desc">{{ item.desc }}</div></el-card></section>
          <section v-if="activeMenu === 'dashboard'" class="dashboard-grid reveal">
            <el-card class="panel-card" shadow="never"><template #header><div class="panel-header"><span>Agent 运营</span><el-tag :type="agentHealth.status === 'ok' ? 'success' : 'warning'">{{ agentPolicyLabel }}</el-tag></div></template><div class="agent-metric-grid"><div><span>发送</span><strong>{{ agentMetrics?.sent ?? '—' }}</strong></div><div><span>完成</span><strong>{{ agentMetrics?.completed ?? '—' }}</strong></div><div><span>平均延迟</span><strong>{{ agentMetrics?.avgLatencyMs ? `${agentMetrics.avgLatencyMs}ms` : '—' }}</strong></div><div><span>有帮助</span><strong>{{ agentMetrics?.feedback?.helpful ?? '—' }}</strong></div></div><div class="agent-policy-line">当前策略：{{ agentPolicyDetail }} · 思考摘要{{ globalModelPolicy.thinkingEnabled === false ? '关闭' : '开启' }} · 故障切换{{ globalModelPolicy.fallbackEnabled === false ? '关闭' : '开启' }}</div><div class="agent-provider-metrics"><span v-for="item in (agentMetrics?.providers || [])" :key="item.provider">{{ item.provider || 'unknown' }} · {{ item.total }}</span><span v-if="!(agentMetrics?.providers || []).length">暂无模型调用记录</span></div></el-card>
            <el-card class="panel-card" shadow="never"><template #header><div class="panel-header"><span>主爬虫监控</span><el-tag :type="sourceAttentionCount ? 'warning' : 'success'">{{ sourceAttentionCount ? `${sourceAttentionCount} 项需关注` : '运行正常' }}</el-tag></div></template><div class="source-monitor-summary">主源：{{ primarySourceLabel }} · 任务：{{ crawlerTaskSummary.running || 0 }} 运行 · {{ crawlerTaskSummary.success || 0 }} 成功 · {{ crawlerTaskSummary.failed || 0 }} 失败</div><div class="source-monitor-list"><div v-for="item in sourceHealthRows" :key="item.name" class="source-monitor-item"><span class="source-monitor-dot" :class="`is-${item.status.toLowerCase()}`"></span><div><strong>{{ item.label }}</strong><small>{{ item.statusText }} · 最近 {{ item.lastMatchCount }} 场</small></div><el-tag size="small" :type="item.status === 'NORMAL' ? 'success' : 'warning'">{{ item.statusText }}</el-tag></div><el-empty v-if="!sourceHealthRows.length" description="暂无启用数据源" :image-size="48" /></div><div v-if="sourceAlerts.length" class="source-alert-list"><div v-for="alert in sourceAlerts.slice(0, 5)" :key="`${alert.source}-${alert.status}`" class="source-alert-item"><el-tag size="small" type="warning">{{ alert.severity || '关注' }}</el-tag><span>{{ alert.source }} · {{ alert.message }}</span></div></div><div v-if="crawlerHistory.length" class="crawler-history"><small>最近任务</small><span v-for="item in crawlerHistory.slice(0, 3)" :key="`${item.taskName}-${item.finishedAt}`">{{ item.taskName }} · {{ item.result }} · {{ item.processedCount || 0 }} 条</span></div></el-card>
            <el-card class="panel-card span-wide" shadow="never"><template #header><div class="panel-header"><span>快捷操作</span><el-tag type="info">Shortcuts</el-tag></div></template><div class="shortcut-grid"><el-button type="success" plain @click="activeMenu='matches'; openCrawlerMatchDialog()">新增比赛维护</el-button><el-button type="primary" plain @click="activeMenu='matches'; syncMatchesNow()">更新主爬虫</el-button><el-button type="warning" plain @click="activeMenu='users'">运营用户</el-button><el-button type="info" plain @click="activeMenu='logs'">查看日志</el-button></div></el-card>
            <el-card class="panel-card span-wide" shadow="never"><template #header><div class="panel-header"><span>最近操作</span><el-tag type="warning">Audit</el-tag></div></template><el-timeline><el-timeline-item v-for="item in recentLogs" :key="item.id || item.createdAt" :timestamp="item.createdAt" :type="item.result === 'SUCCESS' ? 'success' : 'danger'">{{ item.operatorName || '系统' }} · {{ item.action || '-' }} · {{ item.content || '-' }}</el-timeline-item><el-empty v-if="!recentLogs.length" description="暂无操作记录" :image-size="48" /></el-timeline></el-card>
          </section>
          <section v-if="activeMenu === 'sources'" class="admin-panel-section source-console">
            <el-card class="panel-card" shadow="never"><template #header><div class="panel-header"><span>数据源控制台</span><el-tag :type="sourceAttentionCount ? 'warning' : 'success'">{{ sourceAttentionCount ? `${sourceAttentionCount} 项需关注` : '主源正常' }}</el-tag></div></template>
              <el-alert title="当前生产链路只写入 BBC 主爬虫，其他来源仅保留为诊断能力，不会造成重复比赛写入。" type="info" :closable="false" show-icon />
              <div class="source-console-grid"><div v-for="item in sourceHealthRows" :key="item.name" class="source-console-card"><div class="source-console-card-head"><span class="source-monitor-dot" :class="`is-${item.status.toLowerCase()}`"></span><strong>{{ item.label }}</strong><el-tag size="small" :type="item.status === 'NORMAL' ? 'success' : item.status === 'EMPTY' ? 'info' : 'warning'">{{ item.statusText }}</el-tag></div><dl><div><dt>最近返回</dt><dd>{{ item.lastMatchCount }} 场</dd></div><div><dt>传输状态</dt><dd>{{ item.transportHealthy === false ? '不可用' : '可用' }}</dd></div><div><dt>最近成功</dt><dd>{{ formatAdminTime(item.lastSuccess) }}</dd></div><div><dt>数据年龄</dt><dd>{{ formatAge(item.dataAgeSeconds) }}</dd></div></dl></div><el-empty v-if="!sourceHealthRows.length" description="暂无数据源状态" /></div>
              <div v-if="sourceAlerts.length" class="source-alert-list"><div v-for="alert in sourceAlerts" :key="`${alert.source}-${alert.status}-${alert.message}`" class="source-alert-item"><el-tag size="small" type="warning">{{ alert.severity || '关注' }}</el-tag><span>{{ alert.source }} · {{ alert.message }}</span></div></div>
            </el-card>
          </section>
          <section v-if="activeMenu === 'models'" class="admin-panel-section model-lab">
            <el-card class="panel-card" shadow="never"><template #header><div class="panel-header"><span>模型实验室</span><el-tag type="info">只读评估</el-tag></div></template>
              <el-alert title="生产模型由离线训练与门槛审核替换；本页只展示线上已验证表现，不提供网页端直接训练，避免误触导致服务抖动。" type="info" :closable="false" show-icon />
              <div class="model-lab-summary"><div><span>评估窗口</span><strong>近 {{ modelPerformance.windowDays || 30 }} 日</strong></div><div><span>已验证</span><strong>{{ modelPerformance.evaluated ?? '—' }} 场</strong></div><div><span>准确率</span><strong>{{ modelAccuracy }}</strong></div><div><span>生产版本</span><strong class="model-version">{{ (modelPerformance.modelVersions || [])[0] || '统一快照' }}</strong></div></div>
              <div class="model-lab-note"><el-icon><InfoFilled /></el-icon><span>准确率接近基线时不自动宣传“高置信度”。模型适用范围、数据完整性和样本量应与每场预测一起阅读。</span></div>
              <div v-if="modelPerformance.byLeague" class="model-league-list"><div v-for="(count, league) in modelPerformance.byLeague" :key="league"><span>{{ league }}</span><strong>{{ count }} 场预测</strong></div></div>
            </el-card>
          </section>
          <section v-if="activeMenu === 'analytics'" class="admin-panel-section analytics-console">
            <el-card class="panel-card" shadow="never"><template #header><div class="panel-header"><span>行为分析</span><el-tag type="info">近 {{ analyticsSummary.days || 7 }} 日</el-tag></div></template>
              <div class="analytics-summary-grid"><div><span>事件总量</span><strong>{{ analyticsSummary.totalEvents ?? '—' }}</strong></div><div><span>活跃用户</span><strong>{{ analyticsSummary.uniqueUsers ?? '—' }}</strong></div><div><span>埋点状态</span><strong>{{ analyticsSummary.status === 'AVAILABLE' ? '可用' : '待初始化' }}</strong></div></div>
              <el-alert v-if="analyticsSummary.status !== 'AVAILABLE'" :title="analyticsSummary.message || '埋点数据暂不可用'" type="warning" :closable="false" show-icon />
              <div v-if="analyticsSummary.status === 'AVAILABLE'" class="analytics-funnel" aria-label="核心转化漏斗"><span>比赛→预测 {{ analyticsSummary.funnel?.matchToPredictionRate ?? 0 }}%</span><span>预测→Agent {{ analyticsSummary.funnel?.predictionToAgentRate ?? 0 }}%</span></div>
              <div v-if="analyticsSummary.status === 'AVAILABLE'" class="analytics-event-list"><div v-for="item in (analyticsSummary.eventCounts || [])" :key="item.event_name || item.eventName"><span>{{ item.event_name || item.eventName }}</span><strong>{{ item.total }}</strong></div><el-empty v-if="!(analyticsSummary.eventCounts || []).length" description="暂无行为数据" /></div>
            </el-card>
          </section>
          <section v-if="activeMenu === 'matches'"><MatchWorkbench v-model:keyword="crawlerMatchKeyword" v-model:status="crawlerMatchStatus" v-model:date="crawlerMatchDate" :matches="crawlerMatches" :total="crawlerMatchTotal" :page="crawlerMatchPage" :page-size="crawlerMatchPageSize" :error="sectionErrors.matches" @reload="loadMatches" @size-change="handleCrawlerMatchSizeChange" @create="openCrawlerMatchDialog()" @edit="openCrawlerMatchDialog" @delete="deleteCrawlerMatch" /></section>
          <section v-if="activeMenu === 'users'" class="admin-panel-section"><AdminUsersPanel :users="users" v-model:role-filter="userRoleFilter" v-model:status-filter="userStatusFilter" :error="sectionErrors.users" @filter-change="loadUsers" @retry="loadUsers" @user-action="handleUserCommand" /></section>
          <section v-if="activeMenu === 'config'" class="admin-panel-section"><AdminConfigPanel :config="config" :error="sectionErrors.config" @save="saveConfig" @retry="loadConfig" /></section>
          <section v-if="activeMenu === 'logs'" class="admin-panel-section"><AdminLogPanel :logs="logs" v-model:module-filter="logModuleFilter" :error="sectionErrors.logs" @filter-change="loadLogs" @retry="loadLogs" @open-detail="openLogDetail" /></section>
        </el-main>
      </el-container>
    </el-container>
    <AdminCrawlerMatchEditorDialog v-model="crawlerMatchDialogVisible" :form="crawlerMatchForm" @save="saveCrawlerMatch" />
    <el-dialog v-model="syncProgressVisible" title="更新主爬虫数据" width="680px" :close-on-click-modal="!syncRunning" :close-on-press-escape="!syncRunning" :show-close="!syncRunning" class="admin-dialog sync-dialog"><div class="sync-progress-head"><div><div class="sync-progress-title">{{ syncProgressTitle }}</div><div class="sync-progress-subtitle">{{ syncProgressSubtitle }}</div></div><el-tag :type="syncRunning ? 'warning' : (syncProgressFailed ? 'danger' : 'success')">{{ syncRunning ? '同步中' : (syncProgressFailed ? '失败' : '已完成') }}</el-tag></div><el-progress :percentage="syncProgressPercent" :status="syncProgressFailed && !syncRunning ? 'exception' : (syncRunning ? undefined : 'success')" :stroke-width="14" striped striped-flow /><div class="sync-source-list"><div v-for="item in syncProgressSources" :key="item.key" class="sync-source-item"><div class="sync-source-main"><span class="sync-dot" :class="`is-${item.status}`"></span><div><strong>{{ item.label }}</strong><p>{{ item.message }}</p></div></div><el-tag size="small" :type="syncStatusTag(item.status)">{{ syncStatusText(item.status) }}</el-tag></div></div><template #footer><el-button :disabled="syncRunning" @click="syncProgressVisible=false">关闭</el-button><el-button type="primary" :loading="syncRunning" @click="syncMatchesNow">{{ syncRunning ? '正在同步' : '重新同步' }}</el-button></template></el-dialog>
    <el-drawer v-model="logDetailVisible" title="日志详情" size="460px"><el-descriptions :column="1" size="small" border><el-descriptions-item label="时间">{{ currentLog.createdAt || '-' }}</el-descriptions-item><el-descriptions-item label="操作人">{{ currentLog.operatorName || '-' }}</el-descriptions-item><el-descriptions-item label="模块">{{ currentLog.module || '-' }}</el-descriptions-item><el-descriptions-item label="动作">{{ currentLog.action || '-' }}</el-descriptions-item><el-descriptions-item label="对象类型">{{ currentLog.targetType || '-' }}</el-descriptions-item><el-descriptions-item label="对象ID">{{ currentLog.targetId || '-' }}</el-descriptions-item><el-descriptions-item label="内容">{{ currentLog.content || '-' }}</el-descriptions-item><el-descriptions-item label="结果"><el-tag :type="currentLog.result === 'SUCCESS' ? 'success' : 'danger'">{{ currentLog.result || '-' }}</el-tag></el-descriptions-item></el-descriptions></el-drawer>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { InfoFilled } from '@element-plus/icons-vue'
import { adminApi } from '../../api/admin'
import { agentApi, crawlerApi, predictionApi } from '../../api'
import AdminConfigPanel from './AdminConfigPanel.vue'
import AdminCrawlerMatchEditorDialog from './AdminCrawlerMatchEditorDialog.vue'
import AdminLogPanel from './AdminLogPanel.vue'
import AdminUsersPanel from './AdminUsersPanel.vue'
import MatchWorkbench from './MatchWorkbench.vue'

const router = useRouter()
const activeMenu = ref('dashboard')
const crawlerMatches = ref([])
const crawlerMatchTotal = ref(0)
const crawlerMatchPage = ref(1)
const crawlerMatchPageSize = ref(20)
const crawlerMatchKeyword = ref('')
const crawlerMatchStatus = ref('')
const crawlerMatchDate = ref('')
const crawlerMatchDialogVisible = ref(false)
const crawlerMatchForm = reactive({})
const users = ref([])
const logs = ref([])
const config = reactive({})
const userKeyword = ref('')
const userRoleFilter = ref('')
const userStatusFilter = ref('')
const logModuleFilter = ref('')
const dataSourceHealth = ref({ providers: [], primaryOnly: true, primarySource: 'bbc-scores' })
const crawlerHealth = ref({ taskSummary: {}, history: [] })
const agentMetrics = ref(null)
const agentHealth = ref({ status: 'unknown', models: {} })
const modelPerformance = ref({})
const analyticsSummary = ref({})
const sectionErrors = reactive({ matches: '', users: '', config: '', logs: '', summary: '' })
const syncProgressVisible = ref(false)
const syncRunning = ref(false)
const syncProgressFailed = ref(false)
const syncProgressTitle = ref('准备更新主爬虫数据')
const syncProgressSubtitle = ref('正在初始化 BBC 主爬虫同步任务')
const syncProgressPercent = ref(0)
const syncProgressSources = ref([])
const logDetailVisible = ref(false)
const currentLog = reactive({})
const dashboardTodayMatches = ref([])
const lastReloadAt = ref('')

const pageTitle = computed(() => ({ dashboard: '管理总览', matches: '比赛维护工作台', sources: '数据源控制台', models: '模型实验室', analytics: '行为分析', users: '用户运营中心', config: '系统配置中心', logs: '审计与追踪' }[activeMenu.value]))
const activeUserCount = computed(() => users.value.filter(user => user.status === 'ACTIVE').length)
const todaysMatchCount = computed(() => dashboardTodayMatches.value.length)
const metrics = computed(() => [{ label: '今日比赛', value: todaysMatchCount.value, desc: '主爬虫今日采集' }, { label: '比赛总量', value: crawlerMatchTotal.value, desc: '当前生产赛事库' }, { label: '活跃用户', value: activeUserCount.value, desc: '账号状态为 ACTIVE' }, { label: '审计日志', value: logs.value.length, desc: '最近加载记录' }])
const globalModelPolicy = computed(() => agentHealth.value?.models?.configuredPolicy || {})
const agentPolicyDetail = computed(() => { const policy = globalModelPolicy.value; const configured = String(policy.provider || 'auto').toLowerCase(); const providerItems = agentHealth.value?.models?.providers || []; const ready = name => providerItems.some(item => item.provider === name && item.configured); const provider = configured === 'openrouter' && ready('openrouter') ? 'openrouter' : configured === 'scnet' && ready('scnet') ? 'scnet' : configured === 'deepseek' && ready('deepseek') ? 'deepseek' : ready('openrouter') ? 'openrouter' : ready('scnet') ? 'scnet' : 'deepseek'; const labels = { openrouter: 'OpenRouter', scnet: 'SCNet', deepseek: 'DeepSeek' }; const model = policy[provider]?.model || providerItems.find(item => item.provider === provider)?.model || '环境变量默认模型'; return `${labels[provider] || provider} · ${model}` })
const agentPolicyLabel = computed(() => agentHealth.value.status === 'ok' ? '在线' : '需关注')
const primarySourceLabel = computed(() => dataSourceHealth.value.primarySource || 'bbc-scores')
const sourceHealthRows = computed(() => (Array.isArray(dataSourceHealth.value?.providers) ? dataSourceHealth.value.providers : []).filter(item => item.enabled !== false).map(item => ({ name: item.name || item.source || 'unknown', label: item.name === 'bbc-scores' ? 'BBC 主爬虫' : item.name || item.source || '数据源', status: String(item.status || 'UNKNOWN'), statusText: item.statusText || '未检测', lastMatchCount: Number(item.lastMatchCount || 0), transportHealthy: item.transportHealthy, lastSuccess: item.lastSuccess, dataAgeSeconds: item.dataAgeSeconds })))
const sourceAttentionCount = computed(() => sourceHealthRows.value.filter(item => item.status !== 'NORMAL').length)
const crawlerTaskSummary = computed(() => crawlerHealth.value?.taskSummary || {})
const sourceAlerts = computed(() => Array.isArray(dataSourceHealth.value?.alerts) ? dataSourceHealth.value.alerts : [])
const crawlerHistory = computed(() => Array.isArray(crawlerHealth.value?.history) ? crawlerHealth.value.history : [])
const recentLogs = computed(() => logs.value.slice(0, 5))
const modelAccuracy = computed(() => modelPerformance.value.accuracy == null ? '—' : `${Number(modelPerformance.value.accuracy).toFixed(1)}%`)
const formatAdminTime = value => value ? new Date(value).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : '—'
const formatAge = value => { const seconds = Number(value); if (!Number.isFinite(seconds) || seconds < 0) return '—'; if (seconds < 60) return `${Math.round(seconds)} 秒`; if (seconds < 3600) return `${Math.round(seconds / 60)} 分钟`; return `${Math.round(seconds / 3600)} 小时` }

const normalizePageResult = res => {
  if (Array.isArray(res)) return { items: res, total: res.length }
  if (res && Array.isArray(res.items)) return res
  if (res && Array.isArray(res.response)) return { ...res, items: res.response, total: Number(res.total ?? res.response.length) }
  if (res && Array.isArray(res.records)) return { ...res, items: res.records, total: Number(res.total ?? res.records.length) }
  if (res && Array.isArray(res.data?.items)) return res.data
  if (res && Array.isArray(res.data?.response)) return { ...res.data, items: res.data.response, total: Number(res.data.total ?? res.data.response.length) }
  return { items: [], total: 0 }
}
const mapCrawlerMatchRow = row => ({ id: row?.id ?? row?.fixture?.id ?? row?.fixtureId ?? null, fixtureId: row?.fixture?.id ?? row?.fixtureId ?? row?.id ?? null, externalMatchId: row?.externalMatchId ?? row?.external_id ?? '', source: row?.source ?? '', leagueId: row?.league?.id ?? row?.leagueId ?? '', leagueName: row?.league?.name ?? row?.leagueName ?? '', homeTeamId: row?.teams?.home?.id ?? row?.homeTeamId ?? '', homeTeamName: row?.teams?.home?.name ?? row?.homeTeamName ?? '', homeTeamLogo: row?.teams?.home?.logo ?? row?.homeTeamLogo ?? '', awayTeamId: row?.teams?.away?.id ?? row?.awayTeamId ?? '', awayTeamName: row?.teams?.away?.name ?? row?.awayTeamName ?? '', awayTeamLogo: row?.teams?.away?.logo ?? row?.awayTeamLogo ?? '', homeScore: row?.goals?.home ?? row?.homeScore ?? null, awayScore: row?.goals?.away ?? row?.awayScore ?? null, status: row?.fixture?.status?.short ?? row?.status ?? '', matchTime: row?.fixture?.date ?? row?.matchTime ?? '', matchDate: row?.fixture?.date ? String(row.fixture.date).slice(0, 10) : (row?.matchTime ? String(row.matchTime).slice(0, 10) : ''), note: row?.note ?? '' })
const loadMatches = async (page = crawlerMatchPage.value) => { sectionErrors.matches = ''; try { crawlerMatchPage.value = page; const result = normalizePageResult(await adminApi.listCrawlerMatches({ keyword: crawlerMatchKeyword.value, status: crawlerMatchStatus.value, date: crawlerMatchDate.value, page, size: crawlerMatchPageSize.value })); crawlerMatches.value = result.items.map(mapCrawlerMatchRow); crawlerMatchTotal.value = Number(result.total || 0) } catch (error) { sectionErrors.matches = error?.message || '请检查比赛服务是否可用'; crawlerMatches.value = []; crawlerMatchTotal.value = 0 } }
const loadUsers = async () => { sectionErrors.users = ''; try { let result = await adminApi.listUsers(userKeyword.value); if (userRoleFilter.value) result = result.filter(user => user.role === userRoleFilter.value); if (userStatusFilter.value) result = result.filter(user => user.status === userStatusFilter.value); users.value = result } catch (error) { sectionErrors.users = error?.message || '请检查用户服务是否可用'; users.value = [] } }
const loadConfig = async () => { sectionErrors.config = ''; try { Object.assign(config, await adminApi.getConfig()) } catch (error) { sectionErrors.config = error?.message || '请检查配置服务是否可用' } }
const loadLogs = async () => { sectionErrors.logs = ''; try { const result = await adminApi.getLogs(); logs.value = logModuleFilter.value ? result.filter(item => item.module === logModuleFilter.value) : result } catch (error) { sectionErrors.logs = error?.message || '请检查日志服务是否可用'; logs.value = [] } }
const unwrap = result => result?.data || result || {}
const normalizeList = result => { const value = unwrap(result); return Array.isArray(value) ? value : Array.isArray(value.items) ? value.items : Array.isArray(value.response) ? value.response : [] }
const loadDashboardSummary = async () => { sectionErrors.summary = ''; const [matchesResult, healthResult, crawlerResult, metricsResult, agentResult, modelResult, analyticsResult] = await Promise.allSettled([crawlerApi.getTodayMatches(), crawlerApi.getDataSourceHealth(), crawlerApi.getHealth(), agentApi.metrics(7), agentApi.health(), predictionApi.getPerformance(30), adminApi.getAnalyticsSummary(7)]); const errors = []; if (matchesResult.status === 'fulfilled') dashboardTodayMatches.value = normalizeList(matchesResult.value); else errors.push(`今日比赛：${matchesResult.reason?.message || '加载失败'}`); if (healthResult.status === 'fulfilled') dataSourceHealth.value = unwrap(healthResult.value) || { providers: [] }; else errors.push(`数据源状态：${healthResult.reason?.message || '加载失败'}`); if (crawlerResult.status === 'fulfilled') crawlerHealth.value = unwrap(crawlerResult.value) || { taskSummary: {} }; else errors.push(`任务状态：${crawlerResult.reason?.message || '加载失败'}`); if (metricsResult.status === 'fulfilled') agentMetrics.value = unwrap(metricsResult.value); if (agentResult.status === 'fulfilled') agentHealth.value = unwrap(agentResult.value) || { status: 'unknown', models: {} }; else errors.push(`Agent 状态：${agentResult.reason?.message || '加载失败'}`); if (modelResult.status === 'fulfilled') modelPerformance.value = unwrap(modelResult.value) || {}; if (analyticsResult.status === 'fulfilled') analyticsSummary.value = unwrap(analyticsResult.value) || {}; sectionErrors.summary = errors.join('；') }
const loadDashboard = async () => { await Promise.allSettled([loadMatches(1), loadUsers(), loadConfig(), loadLogs(), loadDashboardSummary()]); return Object.values(sectionErrors).every(value => !value) }
const reloadAll = async () => { const ok = await loadDashboard(); lastReloadAt.value = formatAdminTime(new Date()); if (ok) ElMessage.success('已刷新'); else ElMessage.warning('部分模块刷新失败，请查看页面提示后重试'); return ok }
const goFront = () => router.push('/matches')
const handleCrawlerMatchSizeChange = size => { crawlerMatchPageSize.value = size; loadMatches(1) }
const createNewFixtureId = () => Date.now()
const splitMatchDateTime = value => { if (!value) return { matchDate: '', matchTime: '' }; const text = String(value); const [datePart, timePart = ''] = text.includes('T') ? text.split('T') : text.split(' '); return { matchDate: datePart || '', matchTime: (timePart || '').slice(0, 8) } }
const openCrawlerMatchDialog = (row = null) => { const mapped = row ? mapCrawlerMatchRow(row) : {}; const dt = splitMatchDateTime(mapped.matchTime || row?.matchTime); Object.assign(crawlerMatchForm, { id: row?.id ?? null, fixtureId: row?.fixtureId ?? createNewFixtureId(), externalMatchId: row?.externalMatchId || mapped.externalMatchId || '', source: row?.source || 'bbc-scores', leagueId: '', leagueName: '', round: '', venue: '', homeTeamId: '', homeTeamName: '', homeTeamLogo: '', awayTeamId: '', awayTeamName: '', awayTeamLogo: '', homeScore: null, awayScore: null, status: 'NS', matchDate: dt.matchDate, matchTime: dt.matchTime, note: '', ...mapped, matchDate: row ? dt.matchDate : '', matchTime: row ? dt.matchTime : '' }); crawlerMatchDialogVisible.value = true }
const saveCrawlerMatch = async () => { const matchTime = crawlerMatchForm.matchDate ? `${crawlerMatchForm.matchDate}T${(crawlerMatchForm.matchTime || '00:00:00').slice(0, 8)}` : (crawlerMatchForm.matchTime || null); const payload = { ...crawlerMatchForm, fixtureId: crawlerMatchForm.fixtureId ? Number(crawlerMatchForm.fixtureId) : null, externalMatchId: crawlerMatchForm.externalMatchId || String(crawlerMatchForm.fixtureId || ''), matchTime, homeScore: crawlerMatchForm.homeScore === '' || crawlerMatchForm.homeScore == null ? null : Number(crawlerMatchForm.homeScore), awayScore: crawlerMatchForm.awayScore === '' || crawlerMatchForm.awayScore == null ? null : Number(crawlerMatchForm.awayScore) }; if (payload.id) await adminApi.updateCrawlerMatch(payload.id, payload); else await adminApi.saveCrawlerMatch(payload); crawlerMatchDialogVisible.value = false; await loadMatches(crawlerMatchPage.value); ElMessage.success('比赛已保存') }
const deleteCrawlerMatch = async row => { const id = row?.id; if (!id) { ElMessage.warning('未找到可删除的比赛ID'); return } await ElMessageBox.confirm('确认删除该比赛？', '提示'); await adminApi.deleteCrawlerMatch(id); await loadMatches(crawlerMatchPage.value); ElMessage.success('比赛已删除') }
const handleUserCommand = async (command, row) => { if (command === 'toggleRole') await adminApi.updateUserRole(row.id, row.role === 'ADMIN' ? 'USER' : 'ADMIN'); if (command === 'toggleStatus') await adminApi.updateUserStatus(row.id, row.status === 'ACTIVE' ? 'DISABLED' : 'ACTIVE'); await loadUsers() }
const saveConfig = async () => { await adminApi.saveConfig(config); await loadConfig(); ElMessage.success('配置已保存') }
const syncTasks = [{ key: 'bbc-scores', label: 'BBC 主爬虫：今日及未来 7 天赛事', action: () => adminApi.syncUpcomingMatches() }]
const resetSyncProgress = () => { syncProgressFailed.value = false; syncProgressPercent.value = 0; syncProgressTitle.value = '准备更新主爬虫数据'; syncProgressSubtitle.value = '正在初始化 BBC 主爬虫同步任务'; syncProgressSources.value = syncTasks.map(item => ({ ...item, status: 'pending', message: '等待同步' })) }
const updateSyncPercent = () => { const done = syncProgressSources.value.filter(item => ['success', 'error'].includes(item.status)).length; syncProgressPercent.value = syncProgressSources.value.length ? Math.round(done / syncProgressSources.value.length * 100) : 0 }
const syncStatusTag = status => ({ pending: 'info', running: 'warning', success: 'success', error: 'danger' }[status] || 'info')
const syncStatusText = status => ({ pending: '等待', running: '同步中', success: '完成', error: '失败' }[status] || status)
const syncMatchesNow = async () => { if (syncRunning.value) return; resetSyncProgress(); syncProgressVisible.value = true; syncRunning.value = true; try { for (const task of syncTasks) { syncProgressTitle.value = `正在同步：${task.label}`; syncProgressSources.value = syncProgressSources.value.map(item => item.key === task.key ? { ...item, status: 'running', message: '正在请求后端同步接口...' } : item); try { const report = unwrap(await task.action()); syncProgressSources.value = syncProgressSources.value.map(item => item.key === task.key ? { ...item, status: 'success', message: `完成：总计 ${report?.total || 0}，新增 ${report?.inserted || 0}，更新 ${report?.updated || 0}` } : item) } catch (error) { syncProgressFailed.value = true; const message = error?.response?.status === 504 ? '同步超时，主爬虫响应较慢' : (error?.response?.data?.message || error?.message || '同步失败'); syncProgressSources.value = syncProgressSources.value.map(item => item.key === task.key ? { ...item, status: 'error', message } : item) } updateSyncPercent() } syncProgressTitle.value = syncProgressFailed.value ? '主爬虫同步失败' : '主爬虫同步完成'; syncProgressSubtitle.value = syncProgressFailed.value ? '请检查 BBC 来源状态后重试' : '比赛列表正在刷新'; if (syncProgressFailed.value) ElMessage.warning('主爬虫同步失败'); else ElMessage.success('主爬虫同步完成') } finally { syncRunning.value = false; syncProgressPercent.value = 100; await loadMatches(crawlerMatchPage.value); await loadDashboardSummary() } }
const openLogDetail = row => { Object.assign(currentLog, row || {}); logDetailVisible.value = true }
onMounted(async () => { await loadDashboard(); lastReloadAt.value = formatAdminTime(new Date()) })
</script>

